CREATE OR REPLACE FUNCTION public.can_access_salon(p_salon_id uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_salon public.community_salons; BEGIN SELECT * INTO v_salon FROM public.community_salons WHERE id=p_salon_id; IF NOT FOUND OR auth.uid() IS NULL THEN RETURN false; END IF; IF NOT public.is_community_member(v_salon.community_id) OR NOT public.check_salon_eligibility(p_salon_id,auth.uid()) THEN RETURN false; END IF; IF v_salon.visibility='private' THEN RETURN v_salon.created_by=auth.uid() OR EXISTS(SELECT 1 FROM public.community_salon_members m WHERE m.salon_id=p_salon_id AND m.user_id=auth.uid()); END IF; RETURN true; END; $$; CREATE OR REPLACE FUNCTION public.list_community_chat_groups(p_community_id uuid) RETURNS TABLE(id uuid,community_id uuid,name text,description text,visibility text,created_by uuid,created_at timestamptz,updated_at timestamptz,member_count bigint,my_status text,can_manage boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_uid uuid:=auth.uid(); BEGIN IF v_uid IS NULL OR NOT public.is_community_member(p_community_id) THEN RAISE EXCEPTION 'Vous devez être membre de la communauté'; END IF; RETURN QUERY SELECT s.id,s.community_id,s.name,s.description,s.visibility,s.created_by,s.created_at,s.updated_at,CASE WHEN s.visibility='public' OR s.created_by=v_uid OR EXISTS(SELECT 1 FROM public.community_salon_members m WHERE m.salon_id=s.id AND m.user_id=v_uid) THEN (SELECT count(*) FROM public.community_salon_members m WHERE m.salon_id=s.id) ELSE NULL END,CASE WHEN s.created_by=v_uid OR EXISTS(SELECT 1 FROM public.community_salon_members m WHERE m.salon_id=s.id AND m.user_id=v_uid) THEN 'member' ELSE COALESCE((SELECT r.status FROM public.community_salon_join_requests r WHERE r.salon_id=s.id AND r.user_id=v_uid),'none') END,public.community_can(p_community_id,'can_create_salon') FROM public.community_salons s WHERE s.community_id=p_community_id AND (s.visibility='public' OR s.created_by=v_uid OR EXISTS(SELECT 1 FROM public.community_salon_members m WHERE m.salon_id=s.id AND m.user_id=v_uid) OR EXISTS(SELECT 1 FROM public.community_salon_join_requests r WHERE r.salon_id=s.id AND r.user_id=v_uid AND r.status='pending')) ORDER BY s.updated_at DESC,s.created_at DESC; END; $$; GRANT EXECUTE ON FUNCTION public.list_community_chat_groups(uuid) TO authenticated;